	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.apiKeySubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for ApiKey : " + successValue.getApiKeyId());
							  if (successValue.getApiKeyId().equals(apiKeyId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfApiKeyList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("ApiKey test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on apiKey consumed")
					);
			subscriber.apiKeySubscribe( apiKeyId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for ApiKey : " + successValue.getApiKeyId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfApiKeyList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on apiKey for apiKeyId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a ApiKey. 
	 */
	protected ApiKey read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created ApiKey" );

		ApiKey entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read ApiKey with primary key" );
		msg.append( apiKeyId );
		
		ApiKeyFetchOneSummary fetchOneSummary = new ApiKeyFetchOneSummary( apiKeyId );

		try {
			entity = ApiKeyService.getApiKeyInstance().getApiKey( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found ApiKey " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a ApiKey.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a ApiKey." );

		StringBuilder msg = new StringBuilder( "Failed to update a ApiKey : " );        
		ApiKey entity = read();
		UpdateApiKeyCommand command = generateUpdateCommand();
		command.setApiKeyId(entity.getApiKeyId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created ApiKey." );

			// for use later on...
			apiKeyId = entity.getApiKeyId();

			ApiKeyService proxy = ApiKeyService.getApiKeyInstance();  

			proxy.updateApiKey( command ).get();

			LOGGER.info( "-- Successfully saved ApiKey - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + apiKeyId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a ApiKey.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created ApiKey." );

		ApiKey entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read ApiKey with id " + apiKeyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read ApiKey with id " + apiKeyId );

			throw e;
		}

		try{
			ApiKeyService.getApiKeyInstance().delete( new DeleteApiKeyCommand( entity.getApiKeyId() ) ).get();
			LOGGER.info( "-- Successfully deleted ApiKey with id " + apiKeyId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete ApiKey with id " + apiKeyId );

			throw e;
		}
	}

	/**
	 * get all ApiKeys.
	 */
	protected List<ApiKey> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of ApiKeys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all ApiKey : " );        
		List<ApiKey> collection  = new ArrayList<>();

		try {
			// call the static get method on the ApiKeyService
			collection = ApiKeyService.getApiKeyInstance().getAllApiKey();
			assertNotNull( collection, "An Empty collection of ApiKey was incorrectly returned.");
			
			// Now print out the values
			ApiKey entity = null;            
			Iterator<ApiKey> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getApiKeyId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

